// Scan the pending queue on the NAS bind mount, pick the OLDEST PRD by mtime,
// and move it to in-progress. If none, end quietly.
// NOTE: /data/cowork-builds/ is the runtime queue on the NAS bind mount.
// The repo builds/ folder is the reviewable, version-controlled template - see
// docs/00-foundations/_root/AUTONOMOUS-BUILDER-LIFECYCLE.md for the mapping.
const fs = require('fs');
const path = require('path');

const base = '/data/cowork-builds';
const pendingDir = path.join(base, 'pending');
const inProgressDir = path.join(base, 'in-progress');

// Ensure the queue dirs exist (idempotent; fail-safe on first run).
for (const d of [base, pendingDir, inProgressDir, path.join(base, 'done'), path.join(base, 'failed')]) {
  try { fs.mkdirSync(d, { recursive: true }); } catch (e) { /* already exists */ }
}

let entries = [];
try {
  entries = fs.readdirSync(pendingDir)
    .filter(function (n) { return n.endsWith('.md') && n !== '.gitkeep'; })
    .map(function (n) {
      const full = path.join(pendingDir, n);
      const stat = fs.statSync(full);
      return { name: n, full: full, mtimeMs: stat.mtimeMs };
    })
    .sort(function (a, b) { return a.mtimeMs - b.mtimeMs; });
} catch (e) {
  return [{ json: { picked: false, reason: 'pending dir read error: ' + e.message } }];
}

if (entries.length === 0) {
  // Nothing to do this cycle. End quietly.
  return [{ json: { picked: false, reason: 'pending queue empty' } }];
}

const oldest = entries[0];
const dest = path.join(inProgressDir, oldest.name);

try {
  fs.renameSync(oldest.full, dest);
} catch (e) {
  return [{ json: { picked: false, reason: 'move to in-progress failed: ' + e.message, prd: oldest.name } }];
}

return [{
  json: {
    picked: true,
    prd: oldest.name,
    fromPath: oldest.full,
    inProgressPath: dest,
    mtimeMs: oldest.mtimeMs,
    pickedAt: new Date().toISOString()
  }
}];

// Record the pickup state transition as a first-class Event and prepare the
// ntfy push payload. On pickup we LEAVE the PRD in in-progress/ - the out-of-band
// Cowork session moves it to done/ or failed/ when it finishes. That done/failed
// transition is the deferred post-vacation work (needs the real Cowork API).
const fs = require('fs');
const path = require('path');

const base = '/data/cowork-builds';
const eventsPath = path.join(base, 'events.jsonl');

const src = $input.first().json;
const webhookOk = !(src && src.error);

const event = {
  ts: new Date().toISOString(),
  type: 'build_state_transition',
  transition: 'pending->in-progress',
  prd: src.prd || 'unknown',
  inProgressPath: src.inProgressPath || null,
  trigger_webhook_ok: webhookOk,
  workflow: 'wf-autonomous-builder',
  note: 'Pickup recorded. Done/failed transition handled out-of-band until the Cowork API lands.'
};

try {
  fs.appendFileSync(eventsPath, JSON.stringify(event) + '\n');
} catch (e) {
  // Do not fail the run on an events-log write error; surface it in the payload.
  event.events_write_error = e.message;
}

const ntfyMessage = 'Autonomous builder claimed PRD: ' + event.prd +
  ' (pending -> in-progress). Cowork trigger ' + (webhookOk ? 'sent' : 'FAILED - check webhook') + '.';

return [{
  json: {
    event: event,
    ntfy: {
      topic: 'poe-autonomous-builder',
      title: 'Build pickup',
      message: ntfyMessage,
      priority: webhookOk ? 'default' : 'high'
    }
  }
}];
